window.GET204_QUESTIONS=[{"topic":"Topic 1: General, Mechanical & Electrical Components","q":"A student is asked to drill a hole in an aluminium plate using a pillar drill. Which of the following is the least safe practice?","options":["Clamping the plate ﬁrmly to the table before drilling","Wearing safety goggles during drilling","Holding the plate by hand while drilling","Clearing chips with a brush, not with hands"],"answer":"C","id":"GET204-001"},{"topic":"Topic 1: General, Mechanical & Electrical Components","q":"A mechanical workshop uses both manual and electrically powered tools. The most effective way to ensure safety before tool use is:","options":["Posting general rules on the notice board","Training and direct supervision of each student","Allowing students to choose their own PPE","Operating tools at low speed only"],"answer":"B","id":"GET204-002"},{"topic":"Topic 1: General, Mechanical & Electrical Components","q":"While working on an electrical motor, the recommended ﬁrst action is to:","options":["Ground the frame","Switch off power and lock out the supply","Disconnect the neutral only","Wear a helmet"],"answer":"B","id":"GET204-003"},{"topic":"Topic 1: General, Mechanical & Electrical Components","q":"In a mixed workshop, students are asked to identify machines by sound. This approach is risky because:","options":["Students may confuse similar machines","Sound may damage hearing","Noise can distract them from safety hazards","All of the above"],"answer":"D","id":"GET204-004"},{"topic":"Topic 1: General, Mechanical & Electrical Components","q":"When tightening a bolt using a spanner, maximum force should be applied at:","options":["The jaw of the spanner","The middle of the handle","The end of the handle","Either middle or end, it makes no difference"],"answer":"C","id":"GET204-005"},{"topic":"Topic 1: General, Mechanical & Electrical Components","q":"Which of the following is the best deﬁnition of “safe usage” in the context of workshop machines?","options":["Using machines only when the supervisor is present","Using machines according to manufacturer instructions and standard safety practices","Using machines at reduced speeds","Using machines without personal protective equipment"],"answer":"B","id":"GET204-006"},{"topic":"Topic 1: General, Mechanical & Electrical Components","q":"A student receives a minor electric shock from a bench grinder while grinding. The ﬁrst action should be to:","options":["Switch off and unplug the grinder immediately","Pour water on the grinder to cool it","Continue grinding but at lower pressure","Ignore it, as minor shocks are normal"],"answer":"A","id":"GET204-007"},{"topic":"Topic 1: General, Mechanical & Electrical Components","q":"Which of the following is not a general mechanical tool?","options":["Vernier caliper","Micrometer screw gauge","Vise","Capacitor"],"answer":"D","id":"GET204-008"},{"topic":"Topic 1: General, Mechanical & Electrical Components","q":"Which of these statements about supervised hands-on experience is true?","options":["It removes the need for theory classes","It allows students to practice tasks under controlled conditions to build skill and safety habits","It only teaches machine names","It is only needed for ﬁnal-year students"],"answer":"B","id":"GET204-009"},{"topic":"Topic 1: General, Mechanical & Electrical Components","q":"An electrical apprentice is asked to strip wires for a connection. The safest tool to use is:","options":["Kitchen knife","Wire stripper","Hacksaw","Screwdriver"],"answer":"B","id":"GET204-010"},{"topic":"Topic 2: Use of Measuring Instruments (calipers, micrometers, gauges, sine bar, wood planers, saws, sanders, pattern making)","q":"A Vernier caliper with a least count of 0.02 mm shows a main scale reading of 12.00 mm and a Vernier scale reading of 0.14 mm. The actual reading is:","options":["12.00 mm","12.14 mm","12.28 mm","12.02 mm"],"answer":"B","id":"GET204-011"},{"topic":"Topic 2: Use of Measuring Instruments (calipers, micrometers, gauges, sine bar, wood planers, saws, sanders, pattern making)","q":"The micrometer screw gauge is preferred over a Vernier caliper when:","options":["The object is very long","High accuracy for small dimensions is required","Only approximate measurement is needed","Measuring angles"],"answer":"B","id":"GET204-012"},{"topic":"Topic 2: Use of Measuring Instruments (calipers, micrometers, gauges, sine bar, wood planers, saws, sanders, pattern making)","q":"A slip gauge (gauge block) is mainly used to:","options":["Test the hardness of a material","Provide a precision standard length","Measure internal diameter","Check concentricity"],"answer":"B","id":"GET204-013"},{"topic":"Topic 2: Use of Measuring Instruments (calipers, micrometers, gauges, sine bar, wood planers, saws, sanders, pattern making)","q":"The sine bar is used for:","options":["Checking straightness of shafts","Measuring internal diameters","Measuring or setting angles accurately","Balancing rotating parts"],"answer":"C","id":"GET204-014"},{"topic":"Topic 2: Use of Measuring Instruments (calipers, micrometers, gauges, sine bar, wood planers, saws, sanders, pattern making)","q":"If a Vernier caliper’s jaws are worn and the zero error is +0.04 mm, a reading of 15.36 mm on the scale corresponds to an actual measurement of:","options":["15.32 mm","15.36 mm","15.40 mm","15.42 mm"],"answer":"A","id":"GET204-015"},{"topic":"Topic 2: Use of Measuring Instruments (calipers, micrometers, gauges, sine bar, wood planers, saws, sanders, pattern making)","q":"In pattern making for foundry work, patterns are often made oversize because:","options":["To impress clients","Shrinkage of the metal on cooling","To increase machining allowance","All of the above"],"answer":"D","id":"GET204-016"},{"topic":"Topic 2: Use of Measuring Instruments (calipers, micrometers, gauges, sine bar, wood planers, saws, sanders, pattern making)","q":"Which of these is not a linear measuring instrument?","options":["Vernier depth gauge","Micrometer screw gauge","Dial indicator","Bevel protractor"],"answer":"D","id":"GET204-017"},{"topic":"Topic 2: Use of Measuring Instruments (calipers, micrometers, gauges, sine bar, wood planers, saws, sanders, pattern making)","q":"A student needs to check whether a machined block is truly square. The most appropriate instrument is:","options":["Inside caliper","Outside caliper","Engineer’s square","Slip gauge"],"answer":"C","id":"GET204-018"},{"topic":"Topic 2: Use of Measuring Instruments (calipers, micrometers, gauges, sine bar, wood planers, saws, sanders, pattern making)","q":"The principal advantage of a digital micrometer over an analog micrometer is:","options":["It is cheaper","It eliminates human reading error","It is slower","It cannot be recalibrated"],"answer":"B","id":"GET204-019"},{"topic":"Topic 2: Use of Measuring Instruments (calipers, micrometers, gauges, sine bar, wood planers, saws, sanders, pattern making)","q":"For sanding a wooden pattern, the most important factor to control is:","options":["Speed of the sander","Moisture content of wood","Type of abrasive used","All of the above"],"answer":"D","id":"GET204-020"},{"topic":"Topic 3: Machine Shop","q":"In a centre lathe, the feed motion is obtained from:","options":["Carriage handwheel","Headstock spindle","Lead screw and feed rod","Tailstock quill"],"answer":"C","id":"GET204-021"},{"topic":"Topic 3: Machine Shop","q":"The operation of reducing the diameter of a workpiece in a lathe is called:","options":["Facing","Taper turning","Threading","Turning"],"answer":"D","id":"GET204-022"},{"topic":"Topic 3: Machine Shop","q":"The correct sequence for machining a cylindrical piece on the lathe is:","options":["Centre drilling → Mounting between centres → Turning → Facing","Mounting between centres → Facing → Turning","Facing → Centre drilling → Mounting between centres → Turning","Facing → Turning → Centre drilling"],"answer":"C","id":"GET204-023"},{"topic":"Topic 3: Machine Shop","q":"Which of the following milling cutters is used for cutting keyways in shafts?","options":["Slab mill","End mill","Side-and-face cutter","Involute gear cutter"],"answer":"B","id":"GET204-024"},{"topic":"Topic 3: Machine Shop","q":"The primary difference between a shaper and a planer is:","options":["Tool movement versus work movement","Number of tools used","Power required","Both A and C"],"answer":"D","id":"GET204-025"},{"topic":"Topic 3: Machine Shop","q":"A grinding wheel of grade “H” is:","options":["Hard wheel","Medium wheel","Soft wheel","Diamond wheel"],"answer":"C","id":"GET204-026"},{"topic":"Topic 3: Machine Shop","q":"The main purpose of “reaming” after drilling a hole is:","options":["To enlarge the hole quickly","To remove burrs","To obtain a smooth and accurate hole diameter","To make a countersink"],"answer":"C","id":"GET204-027"},{"topic":"Topic 3: Machine Shop","q":"Metal spinning is a process used mainly to produce:","options":["Large ﬂat plates","Symmetrical hollow shapes from sheets","Threads on shafts","Thin wires from rods"],"answer":"B","id":"GET204-028"},{"topic":"Topic 3: Machine Shop","q":"In lathe work, the ratio of cutting speed to feed determines:","options":["Chip thickness","Tool life","Surface ﬁnish","All of the above"],"answer":"D","id":"GET204-029"},{"topic":"Topic 3: Machine Shop","q":"In cylindrical grinding, the workpiece rotates while:","options":["The wheel is stationary","The grinding wheel reciprocates axially","The grinding wheel also rotates","None of the above"],"answer":"C","id":"GET204-030"},{"topic":"Topic 3: Machine Shop","q":"Which of the following is not a part of the lathe carriage assembly?","options":["Cross-slide","Compound rest","Saddle","Tailstock"],"answer":"D","id":"GET204-031"},{"topic":"Topic 3: Machine Shop","q":"In a shaping machine, the return stroke is made faster than the cutting stroke because:","options":["It reduces idle time and increases productivity","It increases chip thickness","It improves surface ﬁnish","It reduces wear on the tool"],"answer":"A","id":"GET204-032"},{"topic":"Topic 3: Machine Shop","q":"For taper turning on a lathe without a taper attachment, the tailstock can be:","options":["Offset","Rotated","Raised","Lowered"],"answer":"A","id":"GET204-033"},{"topic":"Topic 3: Machine Shop","q":"Milling cutters are speciﬁed by:","options":["Diameter, width and number of teeth","Hardness only","Feed per tooth","Machine type used"],"answer":"A","id":"GET204-034"},{"topic":"Topic 3: Machine Shop","q":"A ﬁxture used to hold the workpiece in a lathe when the tailstock is used for support is:","options":["Faceplate","4-jaw chuck","Lathe dog and driving plate","Drill chuck"],"answer":"C","id":"GET204-035"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"The main difference between brazing and soldering is:","options":["Brazing uses ﬁller metal below 200 °C; soldering above 600 °C","Brazing uses ﬁller metal above 450 °C; soldering below 450 °C","Brazing uses no ﬂux but soldering does","Brazing always uses silver alloy; soldering tin-lead"],"answer":"B","id":"GET204-036"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"In oxy-acetylene gas welding, a neutral ﬂame is used when:","options":["More oxygen is required than acetylene","More acetylene is required than oxygen","Equal oxygen and acetylene ﬂow are required","Oxygen is completely shut off"],"answer":"C","id":"GET204-037"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"Which of the following welding processes does not require ﬁller metal?","options":["Gas welding","Arc welding","Resistance spot welding","TIG welding"],"answer":"C","id":"GET204-038"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"The main purpose of ﬂux in soldering is to:","options":["Increase the melting point of solder","Form a protective oxide coating","Clean metal surfaces and prevent oxidation","Increase mechanical strength of soldered joint"],"answer":"C","id":"GET204-039"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"In arc welding, the arc is struck between:","options":["Two electrodes","Electrode and workpiece","Workpiece and ground","Electrode and gas nozzle"],"answer":"B","id":"GET204-040"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"In MIG welding, the shielding gas is generally:","options":["Nitrogen","Carbon dioxide","Argon or argon-based mixtures","Air"],"answer":"C","id":"GET204-041"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"The function of a welding electrode coating is:","options":["Insulate the electrode completely","Provide ﬂux and stabilise the arc","Reduce electrode consumption","Increase the speed of welding only"],"answer":"B","id":"GET204-042"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"Capillary action in soldering and brazing:","options":["Draws molten ﬁller into the joint","Prevents molten ﬁller from entering the joint","Makes ﬁller metal evaporate","Requires high mechanical pressure"],"answer":"A","id":"GET204-043"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"The typical acetylene pressure at the torch for oxy-acetylene welding is about:","options":["1–2 kPa","20–30 kPa","70–100 kPa","700–1000 kPa"],"answer":"C","id":"GET204-044"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"Which hand tool is used to smooth the surface of wood by shaving off thin layers?","options":["Sander","Planer","File","Micrometer"],"answer":"B","id":"GET204-045"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"The main cause of porosity in a weld bead is:","options":["High current","Poor shielding gas or contamination","Using a low melting point ﬁller","Excess preheat"],"answer":"B","id":"GET204-046"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"In gas cutting, the cutting of steel is due to:","options":["Melting of steel by ﬂame heat","Oxidation of steel by high-pressure oxygen jet","Evaporation of steel at high temperature","Removal of steel by mechanical scraping"],"answer":"B","id":"GET204-047"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"Which solder composition is most common for electronics?","options":["50% tin, 50% lead","60% tin, 40% lead","40% tin, 60% lead","90% tin, 10% silver"],"answer":"B","id":"GET204-048"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"The electrode used for arc welding of mild steel is typically:","options":["Copper","Graphite","Coated mild steel core","Tungsten"],"answer":"C","id":"GET204-049"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"The main advantage of TIG (Tungsten Inert Gas) welding over conventional arc welding is:","options":["Uses ﬂux instead of gas","Allows welding of nonferrous metals with high quality","Uses higher currents","Is cheaper and faster for all materials"],"answer":"B","id":"GET204-050"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"Brazing ﬁller metals are typically:","options":["Tin-lead alloys","Aluminium alloys","Copper-zinc or silver-based alloys","Cast iron"],"answer":"C","id":"GET204-051"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"Which of the following is a non-consumable electrode welding process?","options":["Shielded Metal Arc Welding (SMAW)","Submerged Arc Welding (SAW)","Gas Tungsten Arc Welding (GTAW / TIG)","Gas Metal Arc Welding (GMAW / MIG)"],"answer":"C","id":"GET204-052"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"For soldering electronic components, the soldering iron tip temperature is typically:","options":["50–100 °C","100–150 °C","200–250 °C","350–400 °C"],"answer":"D","id":"GET204-053"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"Which of the following ﬂames is used for cutting steel with oxy-acetylene?","options":["Neutral ﬂame","Carburising ﬂame","Oxidising ﬂame","Inverted ﬂame"],"answer":"C","id":"GET204-054"},{"topic":"Topic 4: Hand Tools, Gas and Arc Welding, Cutting, Brazing and Soldering","q":"In gas welding, a backﬁre occurs when:","options":["Gas supply ﬁnishes","Flame burns back into the tip","Pressure in acetylene cylinder drops below 5 kPa","Arc length is too short"],"answer":"B","id":"GET204-055"},{"topic":"Topic 5: Foundry Practice","q":"In foundry practice, the sand used directly for moulding with clay and water is called:","options":["Core sand","Green sand","Loam sand","Facing sand"],"answer":"B","id":"GET204-056"},{"topic":"Topic 5: Foundry Practice","q":"The ability of moulding sand to allow hot gases to escape is called:","options":["Adhesiveness","Permeability","Refractoriness","Cohesiveness"],"answer":"B","id":"GET204-057"},{"topic":"Topic 5: Foundry Practice","q":"The sand applied on the surface of a pattern to prevent sticking is:","options":["Parting sand","Facing sand","Backing sand","Core sand"],"answer":"A","id":"GET204-058"},{"topic":"Topic 5: Foundry Practice","q":"In foundry, a cavity in the mould used to hold molten metal is called:","options":["Sprue","Cope","Mould cavity","Gate"],"answer":"C","id":"GET204-059"},{"topic":"Topic 5: Foundry Practice","q":"The top half of a split mould is called:","options":["Cope","Drag","Flask","Cheek"],"answer":"A","id":"GET204-060"},{"topic":"Topic 5: Foundry Practice","q":"Which of the following is not a moulding tool?","options":["Trowel","Riddle","Riser","Draw spike"],"answer":"C","id":"GET204-061"},{"topic":"Topic 5: Foundry Practice","q":"The purpose of a riser in a mould is:","options":["To allow gases to escape","To feed molten metal to the casting as it solidiﬁes","To support cores","To measure temperature"],"answer":"B","id":"GET204-062"},{"topic":"Topic 5: Foundry Practice","q":"The lower half of a split mould is known as:","options":["Cope","Drag","Flask","Core box"],"answer":"B","id":"GET204-063"},{"topic":"Topic 5: Foundry Practice","q":"The property of sand to withstand high temperatures without breaking down is:","options":["Adhesiveness","Permeability","Refractoriness","Cohesiveness"],"answer":"C","id":"GET204-064"},{"topic":"Topic 5: Foundry Practice","q":"The tool used to compact moulding sand in a ﬂask is called:","options":["Mallet","Ramming hammer","Strike-off bar","Vent wire"],"answer":"B","id":"GET204-065"},{"topic":"Topic 5: Foundry Practice","q":"Which element of a gating system ﬁrst receives molten metal from the ladle?","options":["Gate","Sprue","Runner","Riser"],"answer":"B","id":"GET204-066"},{"topic":"Topic 5: Foundry Practice","q":"A core print in a pattern provides:","options":["A path for gases","Support for cores","A ﬁnish on the casting","A feeding path for molten metal"],"answer":"B","id":"GET204-067"},{"topic":"Topic 5: Foundry Practice","q":"The tool used to make holes for gases to escape in a mould is called:","options":["Strike-off bar","Vent wire","Riddle","Draw spike"],"answer":"B","id":"GET204-068"},{"topic":"Topic 5: Foundry Practice","q":"The metallic chill in casting is used to:","options":["Slow down solidiﬁcation","Increase heat retention","Increase cooling rate and hardness locally","Reduce shrinkage"],"answer":"C","id":"GET204-069"},{"topic":"Topic 5: Foundry Practice","q":"Which defect results from insufﬁcient venting of a mould?","options":["Blowholes","Hot tears","Misrun","Shrinkage cavity"],"answer":"A","id":"GET204-070"},{"topic":"Topic 5: Foundry Practice","q":"The allowance added on a pattern to compensate for metal contraction is:","options":["Shrinkage allowance","Draft allowance","Machining allowance","Shake allowance"],"answer":"A","id":"GET204-071"},{"topic":"Topic 5: Foundry Practice","q":"The process of cleaning the casting after removal from mould is called:","options":["Fettling","Venting","Coating","Ramming"],"answer":"A","id":"GET204-072"},{"topic":"Topic 5: Foundry Practice","q":"Which casting process uses a wax pattern that is melted away?","options":["Sand casting","Investment casting","Die casting","Permanent mould casting"],"answer":"B","id":"GET204-073"},{"topic":"Topic 5: Foundry Practice","q":"Which of these metals is most commonly cast by permanent mould casting?","options":["Steel","Cast iron","Aluminium","Titanium"],"answer":"C","id":"GET204-074"},{"topic":"Topic 5: Foundry Practice","q":"The main function of a gating system is to:","options":["Filter molten metal","Control and direct molten metal into the mould cavity","Vent gases from the mould","Provide a ﬁnish to the casting"],"answer":"B","id":"GET204-075"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"The main purpose of industrial safety is to:","options":["Increase worker speed","Reduce production cost","Prevent injury, damage and loss","Train workers only in machine use"],"answer":"C","id":"GET204-076"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"The ﬁrst step in an effective accident prevention programme is:","options":["Purchasing PPE","Hazard identiﬁcation","Reporting accidents","Conducting training"],"answer":"B","id":"GET204-077"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"Which of the following is an engineering control for accident prevention?","options":["Job rotation","Guarding dangerous machine parts","Posting warning signs","Providing PPE"],"answer":"B","id":"GET204-078"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"The occupational health and safety concept of “ALARP” means:","options":["As Low As Reasonably Practicable","All Labourers Are Required Protected","Avoid Loss And Risk Properly","Automatic Light And Reﬂective Protection"],"answer":"A","id":"GET204-079"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"Safety colour “Red” in the workplace generally indicates:","options":["Caution","Fire equipment or emergency stop","Safe condition","Information signs"],"answer":"B","id":"GET204-080"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"The most frequent cause of industrial accidents is:","options":["Unsafe acts by workers","Unsafe conditions only","Poor weather","Machine breakdowns"],"answer":"A","id":"GET204-081"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"Ergonomics deals primarily with:","options":["Worker salaries","Fitting the job to the worker","Reducing production costs","Preventing machine corrosion"],"answer":"B","id":"GET204-082"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"In ergonomics, the optimum working height of a workbench for standing work is approximately:","options":["At shoulder level","At elbow level","At knee level","At eye level"],"answer":"B","id":"GET204-083"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"Which of these is a personal protective equipment (PPE)?","options":["Fire extinguisher","Safety helmet","Machine guard","Warning sign"],"answer":"B","id":"GET204-084"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"Which safety device automatically cuts power to a machine when a guard is removed?","options":["Safety relay","Lockout-tagout","Interlock","Fuse"],"answer":"C","id":"GET204-085"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"Metrology is the science of:","options":["Metal removal","Measurement","Machines","Meteorology"],"answer":"B","id":"GET204-086"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"Which of these instruments can measure up to 0.01 mm accuracy?","options":["Steel rule","Vernier caliper","Micrometer screw gauge","Dial indicator"],"answer":"C","id":"GET204-087"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"A sine bar is used to measure:","options":["Flatness","Angle","Diameter","Length"],"answer":"B","id":"GET204-088"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"The process of comparing an instrument with a standard of known accuracy is called:","options":["Veriﬁcation","Calibration","Checking","Adjustment"],"answer":"B","id":"GET204-089"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"The safety device used to disconnect electrical supply during maintenance is:","options":["Fuse","Circuit breaker","Lockout-tagout system","Grounding"],"answer":"C","id":"GET204-090"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"In ergonomics, the term “work-rest cycle” refers to:","options":["Machine downtime","Alternating work with rest periods","Shutting down after shifts","Worker shift changes"],"answer":"B","id":"GET204-091"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"The smallest division on a standard vernier caliper is usually:","options":["0.5 mm","0.1 mm","0.01 mm","1 mm"],"answer":"B","id":"GET204-092"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"Which of the following is not a direct accident cost?","options":["Medical expenses","Compensation payments","Overtime wages to other workers","Replacement of damaged equipment"],"answer":"C","id":"GET204-093"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"The concept of “fail-safe design” in safety engineering means:","options":["Workers cannot fail to follow procedure","Equipment automatically shifts to a safe condition when failure occurs","Double the production capacity","Immediate shutdown of all systems"],"answer":"B","id":"GET204-094"},{"topic":"Topic 6: Industrial Safety, Accident Prevention, Ergonomics, and Metrology","q":"The instrument used to check the ﬂatness of a surface plate is:","options":["Dial gauge","Height gauge","Spirit level","Straight edge"],"answer":"D","id":"GET204-095"},{"topic":"Topic 7: Casting Processes","q":"The primary advantage of casting over other manufacturing processes is:","options":["It produces only small parts","Complex shapes can be produced economically","It gives the highest surface ﬁnish automatically","It does not require patterns"],"answer":"B","id":"GET204-096"},{"topic":"Topic 7: Casting Processes","q":"The liquid metal poured into a mould is called:","options":["Ingot","Casting","Melt","Alloy"],"answer":"C","id":"GET204-097"},{"topic":"Topic 7: Casting Processes","q":"Which of these casting processes does not require a pattern?","options":["Sand casting","Investment casting","Die casting","Continuous casting"],"answer":"D","id":"GET204-098"},{"topic":"Topic 7: Casting Processes","q":"In casting, the passageway that leads molten metal from the sprue to the cavity is called:","options":["Runner","Gate","Riser","Ladle"],"answer":"A","id":"GET204-099"},{"topic":"Topic 7: Casting Processes","q":"Which casting defect results from incomplete ﬁlling of the mould cavity?","options":["Cold shut","Blow hole","Misrun","Shrinkage cavity"],"answer":"C","id":"GET204-100"},{"topic":"Topic 7: Casting Processes","q":"The main function of a riser in a mould is to:","options":["Allow gases to escape","Feed molten metal to compensate for shrinkage","Provide access for inspection","Increase cooling rate"],"answer":"B","id":"GET204-101"},{"topic":"Topic 7: Casting Processes","q":"In investment casting (“lost wax” process), the wax pattern is removed by:","options":["Melting","Breaking","Vibrating","Blasting"],"answer":"A","id":"GET204-102"},{"topic":"Topic 7: Casting Processes","q":"Which of the following castings gives the best dimensional accuracy?","options":["Sand casting","Die casting","Investment casting","Permanent mould casting"],"answer":"C","id":"GET204-103"},{"topic":"Topic 7: Casting Processes","q":"In die casting, the mould used is:","options":["Made of sand","Permanent metal mould","Ceramic","Wooden pattern"],"answer":"B","id":"GET204-104"},{"topic":"Topic 7: Casting Processes","q":"The gating system in casting is designed mainly to:","options":["Increase metal temperature","Control ﬂow and minimize turbulence","Reduce mould size","Add alloying elements"],"answer":"B","id":"GET204-105"},{"topic":"Topic 7: Casting Processes","q":"Which of these is not a common defect in casting?","options":["Hot tears","Blow holes","Spatter","Cold shut"],"answer":"C","id":"GET204-106"},{"topic":"Topic 7: Casting Processes","q":"Shell moulding differs from sand moulding mainly because:","options":["It uses water instead of sand","It uses a resin-coated sand to form thin shell moulds","It does not use patterns","It is only for ferrous metals"],"answer":"B","id":"GET204-107"},{"topic":"Topic 7: Casting Processes","q":"In centrifugal casting, the main factor that shapes the casting is:","options":["Gravity","Centrifugal force","Vacuum","Compressed air"],"answer":"B","id":"GET204-108"},{"topic":"Topic 7: Casting Processes","q":"The term “shakeout” in casting refers to:","options":["Pouring molten metal","Removing solidiﬁed casting from the mould","Removing risers from casting","Finishing operations"],"answer":"B","id":"GET204-109"},{"topic":"Topic 7: Casting Processes","q":"Chill blocks in a mould are used to:","options":["Slow down the cooling rate","Control solidiﬁcation and reﬁne grain structure","Reduce the mould size","Prevent metal ﬂow"],"answer":"B","id":"GET204-110"},{"topic":"Topic 7: Casting Processes","q":"A pattern with allowances for shrinkage and machining is necessary because:","options":["Patterns are used only once","Metals expand during solidiﬁcation","Metals shrink during solidiﬁcation and later machining","To reduce pattern cost"],"answer":"C","id":"GET204-111"},{"topic":"Topic 7: Casting Processes","q":"The type of casting best suited for producing long, continuous shapes like billets is:","options":["Sand casting","Investment casting","Continuous casting","Die casting"],"answer":"C","id":"GET204-112"},{"topic":"Topic 7: Casting Processes","q":"The element in the gating system which slows down molten metal velocity and removes slag is:","options":["Runner","Sprue","Skim bob","Gate"],"answer":"C","id":"GET204-113"},{"topic":"Topic 7: Casting Processes","q":"The main advantage of using a cope and drag (two-part mould) over a single mould is:","options":["Easier to store","Allows complex shapes with undercuts","Eliminates need for cores","Uses less sand"],"answer":"B","id":"GET204-114"},{"topic":"Topic 7: Casting Processes","q":"The process of removing the mould material adhered to the casting surface after shakeout is called:","options":["Fettling","Core setting","Ramming","Venting"],"answer":"A","id":"GET204-115"},{"topic":"Topic 8: Metal Forming Processes","q":"Which of the following is not a primary advantage of hot working over cold working?","options":["Increased ductility","Lower forces required","No oxidation or scale formation","Elimination of porosity"],"answer":"C","id":"GET204-116"},{"topic":"Topic 8: Metal Forming Processes","q":"In metal forming, “cold working” generally refers to deformation carried out:","options":["Above the recrystallization temperature","Below the recrystallization temperature","At exactly the melting point","Only at room temperature"],"answer":"B","id":"GET204-117"},{"topic":"Topic 8: Metal Forming Processes","q":"A key disadvantage of cold working is:","options":["Higher strength and hardness","Higher surface ﬁnish","Work hardening and reduced ductility","Improved dimensional accuracy"],"answer":"C","id":"GET204-118"},{"topic":"Topic 8: Metal Forming Processes","q":"Which of the following is a compressive deformation process?","options":["Drawing","Rolling","Extrusion","Forging"],"answer":"D","id":"GET204-119"},{"topic":"Topic 8: Metal Forming Processes","q":"In forging, the main factor controlling grain ﬂow and strength of the part is:","options":["Hammer weight","Temperature of forging","Direction of deformation","Die lubrication"],"answer":"C","id":"GET204-120"},{"topic":"Topic 8: Metal Forming Processes","q":"Which forming process is best for producing long rods or wires of small cross-section?","options":["Rolling","Drawing","Extrusion","Spinning"],"answer":"B","id":"GET204-121"},{"topic":"Topic 8: Metal Forming Processes","q":"In hot rolling, the purpose of “descaling” between passes is to:","options":["Increase ductility","Remove oxide scale from surface","Add lubrication","Cool the workpiece"],"answer":"B","id":"GET204-122"},{"topic":"Topic 8: Metal Forming Processes","q":"In extrusion, the ratio of billet cross-sectional area to extruded product cross-sectional area is called:","options":["Draft","Reduction ratio","Extrusion ratio","Drawing ratio"],"answer":"C","id":"GET204-123"},{"topic":"Topic 8: Metal Forming Processes","q":"Which is true of indirect (backward) extrusion compared to direct (forward) extrusion?","options":["Higher frictional losses","Lower frictional losses","Requires no die","Cannot produce hollow shapes"],"answer":"B","id":"GET204-124"},{"topic":"Topic 8: Metal Forming Processes","q":"Spinning of sheet metal is mainly used to make:","options":["Billets","Hollow, axisymmetric shapes","Flat plates","Threaded rods"],"answer":"B","id":"GET204-125"},{"topic":"Topic 8: Metal Forming Processes","q":"The main difference between hot working and cold working regarding mechanical properties is:","options":["Hot working increases yield strength","Cold working increases ductility","Hot working reduces residual stresses","Cold working reﬁnes grains"],"answer":"C","id":"GET204-126"},{"topic":"Topic 8: Metal Forming Processes","q":"A punch and die set is typically used in:","options":["Forging","Rolling","Press-tool operations like blanking and piercing","Spinning"],"answer":"C","id":"GET204-127"},{"topic":"Topic 8: Metal Forming Processes","q":"The process of bending sheet metal along a straight line using a press brake is called:","options":["Roll forming","Brake forming","Spinning","Drawing"],"answer":"B","id":"GET204-128"},{"topic":"Topic 8: Metal Forming Processes","q":"The advantage of cold rolling over hot rolling is:","options":["Better surface ﬁnish and closer tolerances","Lower power requirement","Lower cost per unit","No work hardening"],"answer":"A","id":"GET204-129"},{"topic":"Topic 8: Metal Forming Processes","q":"Which forming process uses high-velocity ﬂuid or gas to deform the sheet?","options":["Deep drawing","Hydroforming","Spinning","Forging"],"answer":"B","id":"GET204-130"},{"topic":"Topic 8: Metal Forming Processes","q":"In forging, “upsetting” means:","options":["Reducing diameter while increasing length","Increasing diameter while reducing length","Increasing both diameter and length","Reducing both diameter and length"],"answer":"B","id":"GET204-131"},{"topic":"Topic 8: Metal Forming Processes","q":"Which process is best suited for producing seamless tubes?","options":["Drawing","Rolling","Extrusion","Spinning"],"answer":"C","id":"GET204-132"},{"topic":"Topic 8: Metal Forming Processes","q":"A defect called “earing” in deep drawn cups is caused mainly by:","options":["Improper lubrication","Anisotropy of sheet metal","Excessive blank holder pressure","Low die clearance"],"answer":"B","id":"GET204-133"},{"topic":"Topic 8: Metal Forming Processes","q":"Which parameter most strongly affects the force required in rolling?","options":["Roll diameter","Workpiece color","Speed of rolling","Lubrication type"],"answer":"A","id":"GET204-134"},{"topic":"Topic 8: Metal Forming Processes","q":"The process of gradually reducing the thickness of a bar by passing it through rotating dies without removing material is called:","options":["Swaging","Spinning","Planing","Cutting"],"answer":"A","id":"GET204-135"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"Which of the following processes uses a ﬁller metal with a melting point above 450 °C but below the base metals?","options":["Soldering","Brazing","Gas welding","Cold welding"],"answer":"B","id":"GET204-136"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"In arc welding, the function of the ﬂux covering on an electrode is to:","options":["Provide shielding gas and slag","Increase current","Cool the weld","Increase ﬁller metal melting point"],"answer":"A","id":"GET204-137"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"A weld defect called “undercut” is:","options":["Excess metal beyond the weld toe","Groove melted into base metal adjacent to the weld but not ﬁlled","A type of porosity","A small crack in the center of weld"],"answer":"B","id":"GET204-138"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"In gas welding, the highest temperature ﬂame is obtained with:","options":["Neutral ﬂame","Carburizing ﬂame","Oxidizing ﬂame","Cold ﬂame"],"answer":"C","id":"GET204-139"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"For welding aluminum alloys, the best process is usually:","options":["SMAW (Shielded Metal Arc Welding)","GTAW (TIG)","Oxy-acetylene gas welding","Resistance spot welding"],"answer":"B","id":"GET204-140"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"The reason brazed joints are usually stronger than soldered joints is:","options":["Lower temperature used","Stronger capillary action at lower temp","Higher melting point ﬁller gives better metallurgical bonding","No ﬂux required"],"answer":"C","id":"GET204-141"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"Which welding process uses non-consumable tungsten electrode?","options":["TIG (GTAW)","MIG (GMAW)","SMAW","FCAW"],"answer":"A","id":"GET204-142"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"In resistance spot welding, the heat generated at the joint is proportional to:","options":["V²/R","I²R","IR","1/R"],"answer":"B","id":"GET204-143"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"Capillary action is essential in:","options":["TIG welding","Brazing","Gas metal arc welding","Resistance welding"],"answer":"B","id":"GET204-144"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"The ﬁller metal used in soldering is usually based on:","options":["Copper alloys","Tin-lead alloys","Nickel alloys","Titanium alloys"],"answer":"B","id":"GET204-145"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"In submerged arc welding, the granular ﬂux:","options":["Shields the arc and weld pool","Acts as electrode","Creates gas only","Increases arc temperature but leaves no slag"],"answer":"A","id":"GET204-146"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"Which defect arises due to insufﬁcient heat input or poor cleaning in welding aluminum?","options":["Porosity","Undercut","Crater crack","Burn-through"],"answer":"A","id":"GET204-147"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"Brazing is particularly advantageous when:","options":["You need to join dissimilar metals","You need highest strength joints","You want no ﬁller metal","The joint must withstand 1000 °C"],"answer":"A","id":"GET204-148"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"Which of these is not a fusion welding process?","options":["TIG welding","Laser beam welding","Brazing","MIG welding"],"answer":"C","id":"GET204-149"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"The type of joint preparation least suitable for thick plates in arc welding is:","options":["Square butt","Double-V butt","Single-V butt","U-groove"],"answer":"A","id":"GET204-150"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"In soldering, the main role of ﬂux is to:","options":["Provide ﬁller metal","Dissolve and prevent oxides","Act as insulator","Increase joint temperature"],"answer":"B","id":"GET204-151"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"Which welding process produces the deepest penetration and narrowest HAZ for a given heat input?","options":["TIG welding","Oxy-acetylene gas welding","Electron beam welding","Brazing"],"answer":"C","id":"GET204-152"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"One common method to reduce residual stress after welding is:","options":["Increase welding current","Preheat and post-weld heat treatment","Use thicker ﬁller metal","Apply higher clamping force during welding"],"answer":"B","id":"GET204-153"},{"topic":"Topic 9: Metal Joining Processes (Welding, Brazing, Soldering)","q":"Which of these processes does not rely on melting the base material at all?","options":["Friction welding","Brazing","Diffusion bonding","Oxy-fuel gas welding"],"answer":"C","id":"GET204-154"},{"topic":"Topic 10: Heat Treatment of Metals","q":"Which of these is not a primary stage in a typical heat treatment process?","options":["Heating","Soaking","Cooling","Forging"],"answer":"D","id":"GET204-155"},{"topic":"Topic 10: Heat Treatment of Metals","q":"The main objective of annealing is to:","options":["Increase hardness","Increase ductility and relieve internal stresses","Increase brittleness","Make surface hard and core soft"],"answer":"B","id":"GET204-156"},{"topic":"Topic 10: Heat Treatment of Metals","q":"In quenching, the most rapid cooling is obtained in:","options":["Air","Water","Oil","Brine"],"answer":"D","id":"GET204-157"},{"topic":"Topic 10: Heat Treatment of Metals","q":"The process used to reﬁne grain size and remove internal stresses after cold working is:","options":["Normalizing","Stress relieving","Tempering","Hardening"],"answer":"A","id":"GET204-158"},{"topic":"Topic 10: Heat Treatment of Metals","q":"The critical temperature for steel in heat treatment corresponds to:","options":["Melting point of iron","Transformation to austenite","Recrystallization temperature","Ferrite-to-pearlite change"],"answer":"B","id":"GET204-159"},{"topic":"Topic 10: Heat Treatment of Metals","q":"In tempering of hardened steel, the main purpose is to:","options":["Reduce brittleness","Increase hardness","Increase residual stress","Produce martensite"],"answer":"A","id":"GET204-160"},{"topic":"Topic 10: Heat Treatment of Metals","q":"The structure formed when steel is quenched rapidly from the austenitic region is:","options":["Pearlite","Bainite","Martensite","Ferrite"],"answer":"C","id":"GET204-161"},{"topic":"Topic 10: Heat Treatment of Metals","q":"Case hardening produces:","options":["A soft surface and hard core","A hard surface and soft core","Uniform hardness throughout","A brittle surface only"],"answer":"B","id":"GET204-162"},{"topic":"Topic 10: Heat Treatment of Metals","q":"Which of the following is a type of case hardening?","options":["Nitriding","Quenching","Normalizing","Tempering"],"answer":"A","id":"GET204-163"},{"topic":"Topic 10: Heat Treatment of Metals","q":"The process of heating steel below the lower critical temperature and then cooling in air is:","options":["Annealing","Normalizing","Tempering","Quenching"],"answer":"C","id":"GET204-164"},{"topic":"Topic 10: Heat Treatment of Metals","q":"Carburizing is done to:","options":["Increase carbon content at the surface","Decrease carbon content at the surface","Remove residual stresses","Increase ductility"],"answer":"A","id":"GET204-165"},{"topic":"Topic 10: Heat Treatment of Metals","q":"When steel is heated above the upper critical point and cooled slowly in the furnace, the process is called:","options":["Hardening","Normalizing","Annealing","Tempering"],"answer":"C","id":"GET204-166"},{"topic":"Topic 10: Heat Treatment of Metals","q":"Which cooling medium gives the slowest cooling rate during quenching?","options":["Air","Oil","Water","Brine"],"answer":"A","id":"GET204-167"},{"topic":"Topic 10: Heat Treatment of Metals","q":"The isothermal transformation diagram (TTT diagram) for steel shows:","options":["Heat capacity of steel","Rate of cooling vs. hardness","Time-temperature relation for transformation products","Stress vs. strain relation"],"answer":"C","id":"GET204-168"},{"topic":"Topic 10: Heat Treatment of Metals","q":"Austempering produces which microstructure in steel?","options":["Martensite","Pearlite","Bainite","Ferrite"],"answer":"C","id":"GET204-169"},{"topic":"Topic 10: Heat Treatment of Metals","q":"Surface hardening by high-frequency current is called:","options":["Carburizing","Cyaniding","Induction hardening","Flame hardening"],"answer":"C","id":"GET204-170"},{"topic":"Topic 10: Heat Treatment of Metals","q":"The process used to harden only the surface of low-carbon steel without adding carbon is:","options":["Nitriding","Induction hardening","Carburizing","Cyaniding"],"answer":"B","id":"GET204-171"},{"topic":"Topic 10: Heat Treatment of Metals","q":"Sub-zero treatment (cryogenic treatment) of hardened steel primarily aims at:","options":["Increasing ductility","Completing transformation of retained austenite to martensite","Decreasing hardness","Grain reﬁnement"],"answer":"B","id":"GET204-172"},{"topic":"Topic 10: Heat Treatment of Metals","q":"The difference between normalizing and annealing is mainly in:","options":["The heating temperature","The soaking time","The cooling medium","The steel grade"],"answer":"C","id":"GET204-173"},{"topic":"Topic 10: Heat Treatment of Metals","q":"The process of heating steel to about 30–50 °C below the lower critical temperature, soaking, and cooling slowly to remove residual stresses is called:","options":["Stress-relief annealing","Tempering","Spheroidizing","Normalizing"],"answer":"A","id":"GET204-174"},{"topic":"Topic 11: Material Removal Processes","q":"Which of the following is not a conventional material removal process?","options":["Turning","Milling","Electrochemical machining","Drilling"],"answer":"C","id":"GET204-175"},{"topic":"Topic 11: Material Removal Processes","q":"The main difference between conventional and non-conventional material removal processes is:","options":["Use of mechanical energy only in non-conventional","No tool is required in conventional","Non-conventional uses forms of energy other than direct mechanical force","None of the above"],"answer":"C","id":"GET204-176"},{"topic":"Topic 11: Material Removal Processes","q":"In metal cutting, the material is removed in the form of:","options":["Chips","Powder","Vapour","Residue"],"answer":"A","id":"GET204-177"},{"topic":"Topic 11: Material Removal Processes","q":"The cutting speed in turning depends mainly on:","options":["Feed","Depth of cut","Work material and tool material","Cutting ﬂuid only"],"answer":"C","id":"GET204-178"},{"topic":"Topic 11: Material Removal Processes","q":"The material removal rate (MRR) in drilling is proportional to:","options":["Feed × Cutting Speed × Diameter","Feed × Cutting Speed","Cutting Speed only","Feed only"],"answer":"A","id":"GET204-179"},{"topic":"Topic 11: Material Removal Processes","q":"Which process is suitable for making very precise holes in hard materials like carbide?","options":["Drilling","Reaming","Electro Discharge Machining (EDM)","Boring"],"answer":"C","id":"GET204-180"},{"topic":"Topic 11: Material Removal Processes","q":"In grinding, the material removal takes place by:","options":["Single point cutting","Multiple point cutting with abrasive grains","Chemical dissolution","Impact loading"],"answer":"B","id":"GET204-181"},{"topic":"Topic 11: Material Removal Processes","q":"The rake angle of a cutting tool affects mainly:","options":["Tool life","Chip formation and cutting forces","Surface roughness only","Feed rate"],"answer":"B","id":"GET204-182"},{"topic":"Topic 11: Material Removal Processes","q":"The process used to ﬁnish and size drilled holes accurately is:","options":["Boring","Reaming","Drilling","Counterboring"],"answer":"B","id":"GET204-183"},{"topic":"Topic 11: Material Removal Processes","q":"Which of the following is a non-traditional (non-conventional) machining process?","options":["Broaching","Electrochemical Machining (ECM)","Shaping","Milling"],"answer":"B","id":"GET204-184"},{"topic":"Topic 11: Material Removal Processes","q":"In metal cutting, shear plane angle affects:","options":["Chip thickness and cutting force","Only tool wear","Only tool life","None of the above"],"answer":"A","id":"GET204-185"},{"topic":"Topic 11: Material Removal Processes","q":"Which one removes the material using high-velocity abrasive particles carried by air?","options":["Abrasive jet machining (AJM)","EDM","ECM","Shaper"],"answer":"A","id":"GET204-186"},{"topic":"Topic 11: Material Removal Processes","q":"In turning operation, increasing feed rate will:","options":["Reduce cutting force","Increase surface ﬁnish quality","Increase material removal rate","Make tool wear zero"],"answer":"C","id":"GET204-187"},{"topic":"Topic 11: Material Removal Processes","q":"Broaching is mainly used for:","options":["Cutting external threads","Producing complex internal proﬁles quickly","Finishing only","Welding"],"answer":"B","id":"GET204-188"},{"topic":"Topic 11: Material Removal Processes","q":"The difference between boring and reaming is:","options":["Boring enlarges holes, reaming ﬁnishes them accurately","Boring ﬁnishes holes, reaming enlarges them","Both are same","Reaming is only for external surfaces"],"answer":"A","id":"GET204-189"},{"topic":"Topic 11: Material Removal Processes","q":"The process of removing thin layer of metal from a surface using a single point tool in a linear motion is:","options":["Milling","Shaping","Grinding","Broaching"],"answer":"B","id":"GET204-190"},{"topic":"Topic 11: Material Removal Processes","q":"The term “depth of cut” in turning refers to:","options":["Axial feed","Radial distance from original to ﬁnal diameter","Spindle speed","Tool life"],"answer":"B","id":"GET204-191"},{"topic":"Topic 11: Material Removal Processes","q":"In ECM, material is removed by:","options":["Melting and vaporization","Mechanical abrasion","Anodic dissolution in an electrolyte","Impact of abrasive jets"],"answer":"C","id":"GET204-192"},{"topic":"Topic 11: Material Removal Processes","q":"High-speed steel (HSS) tools are mostly used in:","options":["Non-conventional machining","Conventional machining like turning and milling","Only grinding","Only EDM"],"answer":"B","id":"GET204-193"},{"topic":"Topic 11: Material Removal Processes","q":"Tool wear in high-speed machining is mainly caused by:","options":["Mechanical impact","Thermal and chemical processes at the cutting edge","Low cutting speed","High feed only"],"answer":"B","id":"GET204-194"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"Machine tools are primarily used for:","options":["Assembling parts","Removing material to give desired shape and size","Joining parts together","Storing raw materials"],"answer":"B","id":"GET204-195"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"Which of the following is not a machine tool?","options":["Lathe","Milling machine","Shaper","Bench vice"],"answer":"D","id":"GET204-196"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"The machine tool used for producing cylindrical and conical surfaces is:","options":["Lathe","Planer","Grinder","Slotter"],"answer":"A","id":"GET204-197"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"Machine tools are broadly classiﬁed according to:","options":["Tool material only","Source of power, method of control, and type of operation","Size of the workpiece only","Speed only"],"answer":"B","id":"GET204-198"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"Which of the following machine tools uses a rotating multiple-tooth cutter?","options":["Lathe","Milling machine","Shaper","Planer"],"answer":"B","id":"GET204-199"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"The process of ﬁnishing holes to accurate dimensions using a multi-edge tool is carried out on a:","options":["Lathe","Drill press","Reamer machine","Boring machine"],"answer":"D","id":"GET204-200"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"A planer is primarily used to machine:","options":["Long ﬂat surfaces","Internal threads","Cylindrical holes","Gear teeth"],"answer":"A","id":"GET204-201"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"The main distinguishing feature between a shaper and a planer is:","options":["In a shaper, the tool reciprocates; in a planer, the work reciprocates","In a shaper, the work reciprocates; in a planer, the tool reciprocates","Both have reciprocating tools","Both have rotating tables"],"answer":"A","id":"GET204-202"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"Which machine tool is used to cut external or internal gear teeth accurately?","options":["Lathe","Gear hobbing machine","Milling machine only","Planer"],"answer":"B","id":"GET204-203"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"A slotter is mainly used for:","options":["Producing keyways and slots","Turning cylindrical workpieces","Grinding surfaces","Drilling holes"],"answer":"A","id":"GET204-204"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"Which machine tool can perform turning, facing, threading, and parting-off operations?","options":["Milling machine","Shaper","Lathe","Drill press"],"answer":"C","id":"GET204-205"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"The classiﬁcation of machine tools into “general purpose” and “special purpose” is based on:","options":["Their size","The type of work they can perform","Their weight","Their power supply"],"answer":"B","id":"GET204-206"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"Which of these is a special-purpose machine tool?","options":["Centre lathe","Gear shaping machine","Bench grinder","Shaper"],"answer":"B","id":"GET204-207"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"The advantage of CNC over conventional machine tools is:","options":["Higher initial cost","Lower accuracy","Automated, programmable control and higher precision","Requires more manual operation"],"answer":"C","id":"GET204-208"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"The movement of tool relative to the work in a lathe is known as:","options":["Feed","Depth of cut","Stroke","Clearance"],"answer":"A","id":"GET204-209"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"A jig is primarily used with a machine tool to:","options":["Hold and guide the tool","Hold and support the workpiece","Increase tool life","Store accessories"],"answer":"A","id":"GET204-210"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"Fixtures differ from jigs in that:","options":["Fixtures only hold and support the workpiece; jigs also guide the tool","Fixtures guide the tool and workpiece","Jigs hold the workpiece and tool","They are exactly the same"],"answer":"A","id":"GET204-211"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"The machine tool used for sharpening cutting tools by abrasion is:","options":["Planer","Grinder","Slotter","Drill press"],"answer":"B","id":"GET204-212"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"The spindle speed of a machine tool is measured in:","options":["m/s","N·m","rpm","mm/rev"],"answer":"C","id":"GET204-213"},{"topic":"Topic 12: Machine Tools and Classiﬁcation","q":"Machine tools used to remove material from the workpiece using a high-speed rotating abrasive wheel are classiﬁed as:","options":["Milling machines","Grinders","Slotters","Planers"],"answer":"B","id":"GET204-214"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"In orthogonal metal cutting, the shear plane angle is the angle between:","options":["Tool face and chip","Cutting edge and feed direction","Shear plane and direction of cutting speed","Shear plane and tool face"],"answer":"C","id":"GET204-215"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"The main function of a cutting tool’s rake angle is to:","options":["Control chip ﬂow and reduce cutting forces","Increase tool strength","Support the workpiece","Increase friction at tool–chip interface"],"answer":"A","id":"GET204-216"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"The primary deformation zone in metal cutting is located:","options":["Ahead of the tool along the shear plane","At the tool–chip interface only","On the machined surface","Behind the tool"],"answer":"A","id":"GET204-217"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"A negative rake angle on a cutting tool:","options":["Decreases tool life","Increases tool strength but requires more power","Reduces chip ﬂow","Makes chip ﬂow impossible"],"answer":"B","id":"GET204-218"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"The uncut chip thickness in orthogonal cutting is 0.2 mm. The chip thickness after cutting is 0.5 mm. The chip thickness ratio is:","options":["0.4","2.5","0.25","5"],"answer":"A","id":"GET204-219"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"Continuous chips are usually formed when:","options":["Cutting brittle materials at low speed","Cutting ductile materials at high speed with proper lubrication","Cutting ductile materials at very low speed","Cutting cast iron"],"answer":"B","id":"GET204-220"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"Built-up edge (BUE) on a cutting tool is most likely to occur when:","options":["Cutting at high speeds with good lubrication","Cutting at low speed, high friction conditions","Using a tool with a large rake angle","Machining soft plastics"],"answer":"B","id":"GET204-221"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"Which of the following is a secondary cutting motion?","options":["Feed motion","Cutting speed","Shearing","Chip formation"],"answer":"A","id":"GET204-222"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"In metal cutting, the term “orthogonal cutting” refers to:","options":["Tool edge parallel to feed direction","Tool edge perpendicular to direction of motion","Tool edge inclined at any arbitrary angle","Cutting without a tool"],"answer":"B","id":"GET204-223"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"Which of the following does not directly affect the shear plane angle?","options":["Chip thickness ratio","Rake angle of tool","Feed rate","Workpiece hardness"],"answer":"D","id":"GET204-224"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"The shear plane angle φ can be approximately calculated from the chip thickness ratio r and rake angle α using:","options":["φ = 45° + α","tan φ = r cos α /(1 − r sin α )","φ = α + r","tan φ = (1 − r sin α )/ r cos α"],"answer":"B","id":"GET204-225"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"Which type of chip is preferred for automatic machines (better surface ﬁnish, less hazard)?","options":["Continuous chip","Continuous chip with BUE","Discontinuous chip","Serrated chip"],"answer":"C","id":"GET204-226"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"In metal cutting, the region where tool–chip friction occurs is called:","options":["Primary shear zone","Secondary deformation zone","Dead metal zone","Machined surface"],"answer":"B","id":"GET204-227"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"Which parameter directly indicates the material removal rate (MRR) in turning?","options":["Cutting speed only","Feed only","Depth of cut only","Product of cutting speed, feed and depth of cut"],"answer":"D","id":"GET204-228"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"In orthogonal cutting, the chip ﬂow direction is:","options":["Along the cutting edge","Normal to the shear plane","Opposite to feed direction","Random"],"answer":"B","id":"GET204-229"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"The cutting force component acting in the direction of tool travel is called:","options":["Feed force","Thrust force","Cutting force","Friction force"],"answer":"C","id":"GET204-230"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"Which of the following statements is true regarding friction at the tool–chip interface?","options":["Friction always increases with speed","Friction can be reduced by using cutting ﬂuid","Friction has no effect on tool wear","Friction is negligible in all metal cutting"],"answer":"B","id":"GET204-231"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"The depth of cut in a turning operation is:","options":["Distance the tool travels along the work per revolution","Distance from tool tip to workpiece center","Difference between original and ﬁnal radius of workpiece","Angle of tool inclination"],"answer":"C","id":"GET204-232"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"Chip breakers are provided on cutting tools to:","options":["Strengthen the tool","Break long chips into small pieces for safety and easy removal","Increase cutting speed","Increase chip thickness"],"answer":"B","id":"GET204-233"},{"topic":"Topic 13: Simple Theory of Metal Cutting","q":"Which of these conditions is most favourable for reducing cutting forces?","options":["Negative rake angle and low cutting speed","Positive rake angle and high cutting speed","Zero rake angle and low feed","High feed and negative rake"],"answer":"B","id":"GET204-234"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"The cutting force acting on a tool during turning is primarily measured in the:","options":["Axial direction","Radial direction","Tangential direction","Feed direction"],"answer":"C","id":"GET204-235"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"In a lathe operation, the thrust (or feed) force acts:","options":["Parallel to the cutting velocity","Perpendicular to the machined surface","Along the feed direction of the tool","Normal to the tool face"],"answer":"C","id":"GET204-236"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"The radial force in turning tends to:","options":["Push the tool away from the workpiece","Pull the tool into the workpiece","Increase cutting speed","Reduce depth of cut"],"answer":"A","id":"GET204-237"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"The largest component of the total cutting force is usually:","options":["Feed force","Radial force","Cutting (tangential) force","Thrust force"],"answer":"C","id":"GET204-238"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"According to Merchant’s circle diagram, the friction angle β is deﬁned between:","options":["Shear plane and cutting edge","Rake face of tool and resultant force","Normal to tool face and friction force","Shear force and cutting force"],"answer":"C","id":"GET204-239"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"The shear force in metal cutting acts:","options":["Along the shear plane","Perpendicular to the shear plane","Along the rake face","Along the feed direction"],"answer":"A","id":"GET204-240"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"In the Merchant’s force circle, the resultant force R is the vector sum of:","options":["Cutting force and radial force","Friction force and normal to shear plane","Shear force and normal to shear plane","Friction force and normal to tool face"],"answer":"D","id":"GET204-241"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"High radial force during turning will mostly affect:","options":["Tool life by chipping the tool edge","Cutting temperature only","Chip thickness only","Workpiece hardness"],"answer":"A","id":"GET204-242"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"In drilling, the main cutting force acts:","options":["Axially on the drill","Radially on the drill","Circumferentially on the drill","None of the above"],"answer":"A","id":"GET204-243"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"The unit of cutting force in SI is:","options":["kgf","N","J","W"],"answer":"B","id":"GET204-244"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"Which of the following parameters does not directly inﬂuence cutting force?","options":["Cutting speed","Feed rate","Depth of cut","Tool colour"],"answer":"D","id":"GET204-245"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"For a given material, increasing feed and depth of cut will:","options":["Decrease cutting force","Not affect cutting force","Increase cutting force","Make no predictable change"],"answer":"C","id":"GET204-246"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"The angle between shear force and normal to the shear plane is:","options":["Friction angle","Rake angle","Shear angle","Tool angle"],"answer":"C","id":"GET204-247"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"The component of the resultant cutting force acting normal to the shear plane is:","options":["Normal force on shear plane","Friction force","Shear force","Normal force on tool face"],"answer":"A","id":"GET204-248"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"Reducing friction at the tool–chip interface mainly reduces:","options":["Shear force","Normal force on shear plane","Cutting (tangential) force","Feed force only"],"answer":"C","id":"GET204-249"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"A dynamometer used in turning operations typically measures:","options":["Only the torque","All three components of cutting force simultaneously","Only the radial force","Only temperature rise"],"answer":"B","id":"GET204-250"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"The mechanical power required for cutting is equal to:","options":["Cutting force × feed speed","Cutting force × cutting speed","Shear force × chip velocity","Feed force × feed speed"],"answer":"B","id":"GET204-251"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"The efﬁciency of a cutting process can be improved by:","options":["Increasing friction","Reducing shear angle","Using sharp tools and proper rake angle","Increasing radial force"],"answer":"C","id":"GET204-252"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"In orthogonal cutting, the resultant force R makes an angle with:","options":["Shear plane","Tool face normal","Machined surface","Cutting velocity direction"],"answer":"B","id":"GET204-253"},{"topic":"Topic 14: Tool Action and Cutting Forces","q":"The purpose of Merchant’s equation is to:","options":["Relate shear plane angle to rake angle and friction","Determine chip thickness","Calculate temperature rise","Find tool life"],"answer":"A","id":"GET204-254"},{"topic":"Topic 15: Introduction to CNC Machines","q":"The main difference between CNC and conventional machines is:","options":["CNC uses manual controls","CNC uses computer control to automate operations","CNC cannot machine complex shapes","CNC uses only hydraulic systems"],"answer":"B","id":"GET204-255"},{"topic":"Topic 15: Introduction to CNC Machines","q":"In CNC, the smallest programmable movement of an axis is called:","options":["Step size","Feed rate","Increment","Resolution"],"answer":"D","id":"GET204-256"},{"topic":"Topic 15: Introduction to CNC Machines","q":"Which coordinate system is most common in CNC programming?","options":["Polar coordinates","Cartesian coordinates (X, Y, Z)","Cylindrical coordinates","Spherical coordinates"],"answer":"B","id":"GET204-257"},{"topic":"Topic 15: Introduction to CNC Machines","q":"The G-code that speciﬁes absolute programming mode is:","options":["G90","G91","G00","G01"],"answer":"A","id":"GET204-258"},{"topic":"Topic 15: Introduction to CNC Machines","q":"The G-code for incremental programming mode is:","options":["G90","G91","G94","G99"],"answer":"B","id":"GET204-259"},{"topic":"Topic 15: Introduction to CNC Machines","q":"The CNC axis that moves vertically on a milling machine is typically the:","options":["X-axis","Y-axis","Z-axis","C-axis"],"answer":"C","id":"GET204-260"},{"topic":"Topic 15: Introduction to CNC Machines","q":"The machine zero point in CNC machines is also known as:","options":["Work zero","Home position","Reference point","Offset"],"answer":"C","id":"GET204-261"},{"topic":"Topic 15: Introduction to CNC Machines","q":"In CNC, the M-codes generally control:","options":["Axis movement","Miscellaneous functions like coolant, spindle, etc.","Tool paths","Feed rates"],"answer":"B","id":"GET204-262"},{"topic":"Topic 15: Introduction to CNC Machines","q":"The unit of feed rate in CNC milling is typically:","options":["mm/min or inch/min","rev/min","mm/rev","m/s"],"answer":"A","id":"GET204-263"},{"topic":"Topic 15: Introduction to CNC Machines","q":"Tool offsets in CNC are used to:","options":["Change machine speed","Compensate for tool length and radius","Program part zero","Adjust spindle rotation"],"answer":"B","id":"GET204-264"},{"topic":"Topic 15: Introduction to CNC Machines","q":"Which part of a CNC system interprets the program and sends signals to the drives?","options":["Spindle","Servo motor","Controller unit","Coolant system"],"answer":"C","id":"GET204-265"},{"topic":"Topic 15: Introduction to CNC Machines","q":"Closed-loop CNC systems differ from open-loop systems because they:","options":["Have no feedback","Use feedback devices for position veriﬁcation","Cannot run multiple axes","Require manual intervention"],"answer":"B","id":"GET204-266"},{"topic":"Topic 15: Introduction to CNC Machines","q":"The G-code used for rapid positioning is:","options":["G00","G01","G02","G03"],"answer":"A","id":"GET204-267"},{"topic":"Topic 15: Introduction to CNC Machines","q":"The G-code used for linear interpolation (cutting feed) is:","options":["G00","G01","G02","G03"],"answer":"B","id":"GET204-268"},{"topic":"Topic 15: Introduction to CNC Machines","q":"The G-codes G02 and G03 are used for:","options":["Tapping","Circular interpolation (clockwise and counterclockwise)","Tool changes","Canceling offsets"],"answer":"B","id":"GET204-269"},{"topic":"Topic 15: Introduction to CNC Machines","q":"The part of CNC responsible for moving the machine’s slides and spindle as per commands is the:","options":["Servo drive system","Controller screen","Coolant pump","Fixture"],"answer":"A","id":"GET204-270"},{"topic":"Topic 15: Introduction to CNC Machines","q":"In CNC, backlash compensation is used to:","options":["Increase cutting speed","Correct lost motion in drive screws","Increase tool wear","Reduce vibration"],"answer":"B","id":"GET204-271"},{"topic":"Topic 15: Introduction to CNC Machines","q":"The CNC code for tool change (common) is:","options":["G20","Txx","M06","M08"],"answer":"C","id":"GET204-272"},{"topic":"Topic 15: Introduction to CNC Machines","q":"The main advantage of CNC over manual machines in production is:","options":["It eliminates human supervision","It reduces the need for skilled programming","It provides high repeatability and complex shapes with less time","It consumes less electricity"],"answer":"C","id":"GET204-273"},{"topic":"Topic 15: Introduction to CNC Machines","q":"The term “interpolation” in CNC refers to:","options":["Changing spindle speed","Movement of tool between programmed points","Manual operation of the axis","Running the program without the part"],"answer":"B","id":"GET204-274"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"The color bands on a resistor are used to indicate:","options":["Manufacturer’s name","Resistance value and tolerance","Voltage rating","Wattage"],"answer":"B","id":"GET204-275"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"The correct instrument for checking the polarity of a diode is:","options":["Megger","Multimeter","Wattmeter","Ammeter"],"answer":"B","id":"GET204-276"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"Which component stores energy in an electric ﬁeld?","options":["Resistor","Inductor","Capacitor","Diode"],"answer":"C","id":"GET204-277"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"The unit of inductance is:","options":["Farad","Henry","Ohm","Tesla"],"answer":"B","id":"GET204-278"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"The forward voltage drop across a silicon diode is approximately:","options":["0.1 V","0.3 V","0.7 V","1.2 V"],"answer":"C","id":"GET204-279"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"The primary function of a resistor in an electronic circuit is to:","options":["Store charge","Oppose current ﬂow","Generate voltage","Switch signals"],"answer":"B","id":"GET204-280"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"The component used for blocking DC and allowing AC in circuits is:","options":["Inductor","Capacitor","Resistor","Diode"],"answer":"B","id":"GET204-281"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"A transistor can be used as:","options":["A resistor","A capacitor","An ampliﬁer or a switch","An inductor"],"answer":"C","id":"GET204-282"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"In an inductor, the energy is stored in:","options":["Magnetic ﬁeld","Electric ﬁeld","Both electric and magnetic ﬁelds","No ﬁeld"],"answer":"A","id":"GET204-283"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"Which instrument is most suitable to test the continuity of an electrical circuit?","options":["Wattmeter","Multimeter","Oscilloscope","Frequency counter"],"answer":"B","id":"GET204-284"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"The function of a fuse in a circuit is to:","options":["Step up voltage","Prevent excessive current","Store charge","Provide constant current"],"answer":"B","id":"GET204-285"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"The safe way to discharge a capacitor is:","options":["Short it directly with a screwdriver","Connect it across a resistor","Hit it lightly","Reverse its leads"],"answer":"B","id":"GET204-286"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"The basic building block of digital circuits is:","options":["Diode","Transistor","Logic gate","Inductor"],"answer":"C","id":"GET204-287"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"The resistance of a good conductor at room temperature is:","options":["Very high","Zero","Very low","Inﬁnite"],"answer":"C","id":"GET204-288"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"Which of the following is NOT a passive component?","options":["Resistor","Capacitor","Inductor","Transistor"],"answer":"D","id":"GET204-289"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"The symbol for an NPN transistor shows the arrow:","options":["Pointing inward toward the base","Pointing outward from the emitter","Pointing inward to the collector","Pointing outward from the base"],"answer":"B","id":"GET204-290"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"Before handling electronic components, one should discharge static electricity from the body to:","options":["Avoid electric shock","Prevent damaging sensitive components","Save energy","Increase component life"],"answer":"B","id":"GET204-291"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"The main reason for storing electronic components in anti-static bags is:","options":["To prevent dust","To prevent electrostatic discharge damage","To prevent corrosion","To identify them easily"],"answer":"B","id":"GET204-292"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"The proper way to identify an inductor on a circuit board is usually:","options":["By its cylindrical coil shape","By its voltage rating","By its polar marking","By its heat sink"],"answer":"A","id":"GET204-293"},{"topic":"Topic 16: Electrical & Electronic Components: Identiﬁcation, Use & Care","q":"When measuring resistance with a multimeter, the component must be:","options":["Connected to power","Disconnected from power","Heated to high temperature","Connected in series with a battery"],"answer":"B","id":"GET204-294"},{"topic":"Topic 17: Electric Circuits, Wiring Schemes & Measurements","q":"In a residential wiring system, which wire is usually color-coded green or green/yellow?","options":["Neutral wire","Live wire","Earth wire","Phase wire"],"answer":"C","id":"GET204-295"},{"topic":"Topic 17: Electric Circuits, Wiring Schemes & Measurements","q":"A single-pole single-throw (SPST) switch controls:","options":["Two circuits simultaneously","One circuit at a time","Neutral and earth","Three-phase loads"],"answer":"B","id":"GET204-296"},{"topic":"Topic 17: Electric Circuits, Wiring Schemes & Measurements","q":"Which instrument is used to measure electric current directly?","options":["Voltmeter","Ammeter","Wattmeter","Frequency counter"],"answer":"B","id":"GET204-297"},{"topic":"Topic 17: Electric Circuits, Wiring Schemes & Measurements","q":"Which of the following wiring schemes reduces voltage drop and power loss most?","options":["Radial system","Ring main system","Tree system","Loop system"],"answer":"B","id":"GET204-298"},{"topic":"Topic 17: Electric Circuits, Wiring Schemes & Measurements","q":"In a digital measuring instrument, signals are:","options":["Continuous","Quantized and discrete","Purely analog","Magnetic only"],"answer":"B","id":"GET204-299"},{"topic":"Topic 17: Electric Circuits, Wiring Schemes & Measurements","q":"In an AC circuit, a purely capacitive load causes current to:","options":["Lag voltage by 90°","Lead voltage by 90°","Be in phase with voltage","Be zero"],"answer":"B","id":"GET204-300"},{"topic":"Topic 17: Electric Circuits, Wiring Schemes & Measurements","q":"The instrument used to measure frequency is called:","options":["Ammeter","Wattmeter","Frequency counter","Voltmeter"],"answer":"C","id":"GET204-301"},{"topic":"Topic 17: Electric Circuits, Wiring Schemes & Measurements","q":"An RC circuit behaves as a:","options":["Purely resistive load","Low-pass or high-pass ﬁlter depending on conﬁguration","Power ampliﬁer","Current source"],"answer":"B","id":"GET204-302"},{"topic":"Topic 17: Electric Circuits, Wiring Schemes & Measurements","q":"In a household circuit, the fuse is connected in:","options":["Neutral wire","Earth wire","Live wire","Any wire"],"answer":"C","id":"GET204-303"},{"topic":"Topic 17: Electric Circuits, Wiring Schemes & Measurements","q":"A three-pin plug top’s longest pin is for:","options":["Neutral","Live","Earth","None of the above"],"answer":"C","id":"GET204-304"},{"topic":"Topic 17: Electric Circuits, Wiring Schemes & Measurements","q":"An analog voltmeter measures:","options":["Only DC","Only AC","Both AC and DC depending on design","Frequency only"],"answer":"C","id":"GET204-305"},{"topic":"Topic 17: Electric Circuits, Wiring Schemes & Measurements","q":"The correct connection of an ammeter in a circuit is:","options":["In parallel with the load","In series with the load","Across the power supply","Between earth and neutral"],"answer":"B","id":"GET204-306"},{"topic":"Topic 17: Electric Circuits, Wiring Schemes & Measurements","q":"In a 230 V supply, if neutral wire breaks, the connected appliances:","options":["Will stop working","May get full line voltage and be damaged","Will automatically be grounded","Will operate at half voltage"],"answer":"B","id":"GET204-307"},{"topic":"Topic 17: Electric Circuits, Wiring Schemes & Measurements","q":"The process of measuring an unknown voltage by comparison with a known reference is called:","options":["Ampliﬁcation","Rectiﬁcation","Calibration","Null measurement"],"answer":"D","id":"GET204-308"},{"topic":"Topic 17: Electric Circuits, Wiring Schemes & Measurements","q":"Which of the following is NOT a type of digital electrical measurement?","options":["Digital multimeter","Digital frequency meter","Digital oscilloscope","Analogue galvanometer"],"answer":"D","id":"GET204-309"},{"topic":"Topic 17: Electric Circuits, Wiring Schemes & Measurements","q":"The advantage of digital instruments over analog is:","options":["Lower cost always","Better immunity to noise and easier data storage","More complex display","No power needed"],"answer":"B","id":"GET204-310"},{"topic":"Topic 17: Electric Circuits, Wiring Schemes & Measurements","q":"When measuring resistance of a component using a digital multimeter, the leads should be:","options":["Shorted ﬁrst to zero the meter","Connected directly to AC mains","Connected across a live circuit","Disconnected from the component"],"answer":"A","id":"GET204-311"},{"topic":"Topic 17: Electric Circuits, Wiring Schemes & Measurements","q":"The symbol “~” on a measuring instrument typically indicates:","options":["Direct current","Alternating current","Ground","Neutral"],"answer":"B","id":"GET204-312"},{"topic":"Topic 18: Household & Industrial Energy Consumption Measurements","q":"The unit of electrical energy commonly used in billing households is:","options":["Joule","Watt","Kilowatt-hour","Ampere-hour"],"answer":"C","id":"GET204-313"},{"topic":"Topic 18: Household & Industrial Energy Consumption Measurements","q":"A house consumes 5 kW for 3 hours. How many kWh is consumed?","options":["15","8","5","1.5"],"answer":"A","id":"GET204-314"},{"topic":"Topic 18: Household & Industrial Energy Consumption Measurements","q":"The instrument used to measure electrical energy directly is:","options":["Ammeter","Energy meter","Wattmeter","Voltmeter"],"answer":"B","id":"GET204-315"},{"topic":"Topic 18: Household & Industrial Energy Consumption Measurements","q":"In a single-phase energy meter, the braking torque is produced by:","options":["Current coil","Voltage coil","Permanent magnet","Aluminium disc"],"answer":"C","id":"GET204-316"},{"topic":"Topic 18: Household & Industrial Energy Consumption Measurements","q":"Diversity factor is:","options":["Always less than 1","Always equal to 1","Always greater than 1","Can’t say"],"answer":"C","id":"GET204-317"},{"topic":"Topic 18: Household & Industrial Energy Consumption Measurements","q":"Power factor is the ratio of:","options":["Apparent power to real power","Real power to apparent power","Reactive power to real power","Apparent power to reactive power"],"answer":"B","id":"GET204-318"},{"topic":"Topic 18: Household & Industrial Energy Consumption Measurements","q":"Which type of load affects the power factor most?","options":["Purely resistive","Purely capacitive","Inductive","Resistive-inductive balanced"],"answer":"C","id":"GET204-319"},{"topic":"Topic 18: Household & Industrial Energy Consumption Measurements","q":"The most accurate way to measure industrial energy consumption over time is to use:","options":["Stop watch and ammeter","Digital energy meter with data logging","Handheld voltmeter","Clamp meter only"],"answer":"B","id":"GET204-320"},{"topic":"Topic 18: Household & Industrial Energy Consumption Measurements","q":"A three-phase energy meter measures:","options":["Current only","Voltage only","Energy of each phase separately and sums internally","Reactive energy only"],"answer":"C","id":"GET204-321"},{"topic":"Topic 18: Household & Industrial Energy Consumption Measurements","q":"Which quantity is NOT needed to calculate energy consumption of a single device?","options":["Operating time","Rated voltage","Rated current","Frequency of the supply"],"answer":"D","id":"GET204-322"},{"topic":"Topic 18: Household & Industrial Energy Consumption Measurements","q":"A machine rated 15 kW operates at 0.8 power factor for 4 hours. The energy consumed in kWh is:","options":["60","48","15","75"],"answer":"B","id":"GET204-323"},{"topic":"Topic 18: Household & Industrial Energy Consumption Measurements","q":"A wattmeter reads:","options":["Apparent power","Real power","Reactive power","None"],"answer":"B","id":"GET204-324"},{"topic":"Topic 18: Household & Industrial Energy Consumption Measurements","q":"Energy cost is calculated as:","options":["Power × Voltage","Energy consumed × Tariff rate","Current × Resistance","Energy consumed × Frequency"],"answer":"B","id":"GET204-325"},{"topic":"Topic 18: Household & Industrial Energy Consumption Measurements","q":"The main reason to measure industrial energy consumption at different times of day is to:","options":["Maintain voltage","Determine load patterns and peak demand","Check wiring faults","Test power factor correction capacitors"],"answer":"B","id":"GET204-326"},{"topic":"Topic 18: Household & Industrial Energy Consumption Measurements","q":"Which instrument is used to measure reactive energy (kVARh)?","options":["Power factor meter","VAR meter","Energy meter","Wattmeter"],"answer":"B","id":"GET204-327"},{"topic":"Topic 18: Household & Industrial Energy Consumption Measurements","q":"A load draws 20 A at 240 V for 5 hours. Energy consumed in kWh is:","options":["24","20","5","10"],"answer":"A","id":"GET204-328"},{"topic":"Topic 18: Household & Industrial Energy Consumption Measurements","q":"Time-of-use (TOU) energy meters are designed to:","options":["Record energy separately for peak and off-peak periods","Record only maximum demand","Record only reactive power","Record voltage dips"],"answer":"A","id":"GET204-329"},{"topic":"Topic 18: Household & Industrial Energy Consumption Measurements","q":"The common household device that indirectly measures energy is:","options":["Smart plug energy monitor","Thermostat","Doorbell transformer","Surge protector"],"answer":"A","id":"GET204-330"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"Energy conservation in households mainly focuses on:","options":["Reducing current only","Reducing power wastage","Reducing voltage supply","Increasing energy bills"],"answer":"B","id":"GET204-331"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"The main goal of energy conservation in industries is:","options":["To increase production time","To reduce operating costs and improve efﬁciency","To reduce employee wages","To reduce voltage ﬂuctuations"],"answer":"B","id":"GET204-332"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"Which of the following is NOT an energy conservation measure in lighting?","options":["Using LED bulbs","Using daylight where possible","Leaving lights on continuously","Installing occupancy sensors"],"answer":"C","id":"GET204-333"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"Power factor correction helps conserve energy by:","options":["Increasing supply voltage","Reducing reactive power losses","Stopping load current","Reducing transformer size"],"answer":"B","id":"GET204-334"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"Energy audit in an industrial plant aims at:","options":["Counting number of machines","Identifying energy saving opportunities","Improving plant aesthetics","Replacing all cables"],"answer":"B","id":"GET204-335"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"Which of the following is an example of passive energy conservation?","options":["Installing solar panels","Using natural ventilation and daylight","Using diesel generator backup","Running motors at full load always"],"answer":"B","id":"GET204-336"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"The energy consumption of an electric motor can be reduced by:","options":["Running it at higher than rated speed","Switching off during no-load periods","Reducing supply frequency arbitrarily","Increasing load torque arbitrarily"],"answer":"B","id":"GET204-337"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"Which equipment can store energy for later use, reducing peak demand?","options":["Capacitors","Batteries","Transformers","Relays"],"answer":"B","id":"GET204-338"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"Installing variable speed drives (VSDs) on pumps and fans helps in:","options":["Increasing reactive power","Improving motor insulation","Saving energy by matching speed to load","Reducing supply voltage"],"answer":"C","id":"GET204-339"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"In buildings, the largest energy savings often come from:","options":["Painting walls","Improving insulation and HVAC efﬁciency","Adding decorative lighting","Using more electric heaters"],"answer":"B","id":"GET204-340"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"Which renewable energy source can reduce household electricity bills the most directly?","options":["Diesel generator","Solar photovoltaic panels","Gas-ﬁred boiler","Kerosene lamp"],"answer":"B","id":"GET204-341"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"Load shifting as an energy conservation strategy means:","options":["Reducing total energy used","Moving energy use from peak to off-peak times","Increasing connected load","Switching off all loads permanently"],"answer":"B","id":"GET204-342"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"Energy-efﬁcient motors are designed to:","options":["Draw more current for same load","Have lower losses and higher efﬁciency","Work only at full load","Work at lower voltage only"],"answer":"B","id":"GET204-343"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"The ﬁrst step in any energy conservation plan is:","options":["Purchase new equipment","Conduct an energy audit","Switch off all power","Hire more workers"],"answer":"B","id":"GET204-344"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"The use of capacitors in power systems conserves energy by:","options":["Adding more voltage","Reducing line current and losses","Lowering frequency","Storing energy indeﬁnitely"],"answer":"B","id":"GET204-345"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"Which is a direct method of conserving electrical energy in households?","options":["Using appliances with high star ratings","Running appliances continuously","Using incandescent lamps","Ignoring standby power losses"],"answer":"A","id":"GET204-346"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"Peak demand charges in electricity bills can be reduced by:","options":["Using more appliances simultaneously","Implementing demand-side management","Ignoring load schedules","Increasing supply voltage"],"answer":"B","id":"GET204-347"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"Energy conservation also beneﬁts the environment by:","options":["Increasing greenhouse gas emissions","Reducing resource depletion and pollution","Increasing heat island effect","Increasing waste generation"],"answer":"B","id":"GET204-348"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"Which of these is an example of cogeneration (combined heat and power) saving energy?","options":["Running two generators side by side","Using waste heat from power generation to produce steam","Using diesel instead of petrol","Running motors at full speed"],"answer":"B","id":"GET204-349"},{"topic":"Topic 19: Practical Energy Conservation Principles","q":"Energy conservation in industrial compressed air systems can be achieved by:","options":["Operating at higher than necessary pressure","Fixing air leaks and using efﬁcient compressors","Running compressors at all times","Ignoring maintenance schedules"],"answer":"B","id":"GET204-350"}];